"""Customer insight endpoints for the account team."""

from __future__ import annotations

from typing import Any

from orders.application.customer_service import CustomerService
from orders.application.errors import CustomerNotFound
from orders.application.order_service import OrderService
from orders.controllers.http import InvalidRequest, Response, bad_request, not_found, require_positive_int


class CustomerInsightsController:
    def __init__(self, orders: OrderService, customers: CustomerService) -> None:
        self._orders = orders
        self._customers = customers

    def handle_order_history(self, customer_id: str) -> Response:
        """A customer's orders, newest first, with totals as reported by the order summary."""
        try:
            orders = self._orders.list_for_customer(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        # Order ids are issued in creation order, so reversing gives newest first.
        history: list[dict[str, Any]] = [
            {"order_id": order.order_id, "status": order.status,
             "total_cents": self._orders.summarize(order).total_cents}
            for order in reversed(orders)
        ]
        return Response(200, {"customer_id": customer_id, "orders": history})

    def handle_lifetime_value(self, customer_id: str) -> Response:
        """Number of non-cancelled orders and the sum of their totals, in cents."""
        try:
            order_count, lifetime_value = self._lifetime_value(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        return Response(200, {"customer_id": customer_id, "order_count": order_count,
                              "lifetime_value_cents": lifetime_value})

    def handle_top_customers(self, limit: Any) -> Response:
        """Customers with the highest lifetime value (non-zero only), ties broken by customer_id."""
        try:
            limit = require_positive_int(limit, "limit")
        except InvalidRequest as exc:
            return bad_request(exc)
        ranked = []
        for customer in self._customers.list_all():
            _, lifetime_value = self._lifetime_value(customer.customer_id)
            if lifetime_value > 0:
                ranked.append((lifetime_value, customer))
        ranked.sort(key=lambda entry: (-entry[0], entry[1].customer_id))
        return Response(200, {"customers": [
            {"customer_id": customer.customer_id, "name": customer.name,
             "lifetime_value_cents": lifetime_value}
            for lifetime_value, customer in ranked[:limit]
        ]})

    def _lifetime_value(self, customer_id: str) -> tuple[int, int]:
        """(count of non-cancelled orders, sum of their totals). Raises CustomerNotFound."""
        active = [order for order in self._orders.list_for_customer(customer_id)
                  if order.status != "cancelled"]
        return len(active), sum(self._orders.summarize(order).total_cents for order in active)

